// План specs/audit-log.md, 4.1 (кейс AL-07, шаги 1–2). Супер-админ, бизнес test. Только просмотр. @prod-safe
import { test, expect } from '@playwright/test';
import { setLanguage } from '../admin-plans/plans-helpers';
import { openAuditLogTab, auditRows, chooseAuditFilter } from './audit-helpers';

test.use({ storageState: '../auth/admin.json' });

test.describe('Admin Panel — Audit log (#fc4fa4)', () => {
  test('Super-admin Audit log has entries and the Coupons filter leaves only coupon entries #fc4fa4 @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'en');
    await openAuditLogTab(page);

    for (const h of ['When', 'Who', 'What', 'Account / member']) {
      await expect(page.getByText(h, { exact: true }).first(), `колонка «${h}»`).toBeVisible();
    }
    const rows = auditRows(page);
    await expect(rows.first(), 'в журнале есть записи').toBeVisible({ timeout: 30_000 });

    await chooseAuditFilter(page, 'Coupons');
    const coupon = /Coupon (created|changed|disabled|attached to an account|detached from its account)/;
    await expect(rows.filter({ hasText: coupon }).first(), 'есть купонные записи').toBeVisible({ timeout: 30_000 });
    // Все строки — купонные: некупонных 0
    await expect(rows.filter({ hasNotText: coupon }), 'после фильтра Coupons только купонные записи').toHaveCount(0);
    await expect(page.getByText(/Role changed|Plan (granted|changed|revoked)/)).toHaveCount(0);
  });
});
